import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// VIVAT · Clínica e Vacinação (cliente Luana Faustino, id luana). "Jornal Vivat | Alerta de saúde": notícia da menina de
// 8 anos que morreu de meningite em Luís Eduardo Magalhães (BA). Roteiro do cliente palavra por palavra, voz Roberta
// (src/voz-v1.mp3, 48,5 s). Tom sério e animação simples, como o cliente pediu: nada quica, o texto entra por máscara e fica.
// Identidade do cliente: lilás #954EA4 nos textos, roxo escuro no destaque, fonte Helvetica (Neue, do sistema), o fundo
// lilás que eles mandaram. Proibido pelo cliente: seringa e agulha. A mascote Vivi só aparece no CTA final.
// Arco de cor: claro (notícia) → roxo escuro (agravamento, sintomas) → claro de novo (vacina, CTA).
// V2 (pedido): sem pausa e mais fluida. Voz = src/voz-v2.wav (a mesma tomada da v1 com os silêncios encurtados para
// ~0,15–0,2 s, 42,8 s); todos os tempos foram convertidos da v1 pela tabela edit/cortes-v2.json. Mais movimento sem
// acelerar: câmera com deslize próprio em cada cena, entradas e saídas mais longas e cruzadas, empurrão suave de câmera
// nas palavras-chave, fotos entrando inclinadas.
// V3 (pedido): mais inversão de cor no fundo. O fundo troca a cada cena, sempre em círculo saindo de um ponto da
// cena: claro → roxo escuro → claro → lilás chapado → escuro → claro → escuro → claro → lilás chapado (CTA, logo branco).
// Mesma voz e mesmos tempos da v2 (src/voz-v2.wav, áudio edit/mix-v2.wav).
// V4 (pedido do cliente): a foto da criança saiu por direitos autorais. No lugar, uma cena "3D" montada aqui: o vírus da
// referência deles desfocado ao fundo e uma boneca de pano desenhada em SVG com volume (degradês, luz e sombra), dormindo,
// em camadas com profundidades diferentes (parallax). Resto igual à v3.
// Tempos = tempos da locução (t = 0 é o começo do áudio; o vídeo tem LEAD de entrada).

export const VV4_FPS = 30;
const LEAD = 0.3;
export const VV4_FRAMES = Math.round((LEAD + 42.8 + 2.1) * VV4_FPS);

const F = '"Helvetica Neue", Helvetica, Arial, sans-serif';
const LIL = "#954EA4";
const LIL_L = "#D9B8E2";
const DEEP = "#4A1D5C";
const NIGHT = "#2B1035";
const WHITE = "#FFFFFF";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const IN = Easing.bezier(0.55, 0, 0.9, 0.4);
const k = (t: number, a: number, d = 0.55) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const ein = (t: number, a: number, d = 0.35) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

// trocas de cena (tempo da voz)
const S2 = 3.15, S3 = 5.6, S4 = 10.61, S5 = 18.4, S6 = 23.58, S7 = 26.15, S8 = 33.17, S9 = 39.33;

// ───────── peças ─────────
// texto que sobe da linha (máscara) e fica parado; some no mesmo lugar
const Mask: React.FC<{ t: number; at: number; out?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ t, at, out, children, style }) => {
  const e = k(t, at, 0.6);
  const o = out === undefined ? 0 : ein(t, out, 0.3);
  return (
    <div style={{ overflow: "hidden", paddingBottom: "0.08em", marginBottom: "-0.08em", ...style }}>
      <div style={{ transform: `translateY(${((1 - e) * 105 + o * -105).toFixed(2)}%)`, opacity: Math.min(1, e * 3) * (1 - o * 0.6) }}>{children}</div>
    </div>
  );
};

const Head: React.FC<{ size: number; color: string; children: React.ReactNode; weight?: number; ls?: string }> = ({ size, color, children, weight = 700, ls = "-0.02em" }) => (
  <div style={{ fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1.04, letterSpacing: ls, color, whiteSpace: "nowrap", textAlign: "center" }}>{children}</div>
);

// destaque em faixa chapada: a faixa abre da esquerda e o texto sobe dentro dela
const Pill: React.FC<{ t: number; at: number; out?: number; size: number; bg: string; color?: string; children: React.ReactNode }> = ({ t, at, out, size, bg, color = WHITE, children }) => {
  const w = k(t, at, 0.5);
  const o = out === undefined ? 0 : ein(t, out, 0.3);
  return (
    <div style={{ position: "relative", padding: `${size * 0.14}px ${size * 0.32}px ${size * 0.16}px`, opacity: 1 - o }}>
      <div style={{ position: "absolute", inset: 0, background: bg, borderRadius: size * 0.18, clipPath: `inset(0 ${((1 - w) * 100).toFixed(2)}% 0 0 round ${size * 0.18}px)` }} />
      <Mask t={t} at={at + 0.12}>
        <Head size={size} color={color}>{children}</Head>
      </Mask>
    </div>
  );
};

