// cena: entra já em movimento (sobe e assenta), sai acelerando; cada cena com a sua câmera
const Scene: React.FC<{ t: number; a: number; b: number; children: React.ReactNode; enter?: "up" | "zoom" | "side" | "none"; exit?: "up" | "zoom" | "side" | "fade" | "none"; drift?: number; pan?: [number, number] }> = ({ t, a, b, children, enter = "up", exit = "up", drift = 0.06, pan = [0, -40] }) => {
  if (t < a - 0.05 || t > b + 0.5) return null;
  const e = k(t, a, 0.8);
  const x = ein(t, b - 0.12, 0.5);
  // câmera: aproxima e desliza o tempo todo, devagar, numa direção própria da cena
  const c = io(t, a - 0.3, b + 0.5);
  let tx = pan[0] * c, ty = pan[1] * c, sc = 1 + drift * c, op = 1, bl = 0, rot = 0;
  if (enter === "up") { ty += (1 - e) * 280; rot += (1 - e) * 1.2; }
  if (enter === "zoom") sc *= 0.8 + 0.2 * e;
  if (enter === "side") { tx += (1 - e) * 440; rot += (1 - e) * -1.5; }
  if (enter !== "none") { op *= Math.min(1, e * 2.2); bl += (1 - e) * 12; }
  if (exit === "up") { ty -= x * 320; op *= 1 - x; bl += x * 14; }
  if (exit === "zoom") { sc *= 1 + x * 0.32; op *= 1 - x; bl += x * 16; }
  if (exit === "side") { tx -= x * 460; rot += x * 1.5; op *= 1 - x; bl += x * 12; }
  if (exit === "fade") { op *= 1 - x; sc *= 1 + x * 0.06; }
  return (
    <AbsoluteFill style={{ transformOrigin: "50% 30%", transform: `translate(${tx.toFixed(1)}px, ${ty.toFixed(1)}px) scale(${sc.toFixed(4)}) rotate(${rot.toFixed(3)}deg)`, opacity: op, filter: bl > 0.05 ? `blur(${bl.toFixed(1)}px)` : undefined }}>
      {children}
    </AbsoluteFill>
  );
};

