// fundo: L = lilás claro do cliente, D = roxo escuro, P = lilás chapado da marca
type Mode = "L" | "D" | "P";
const Bg: React.FC<{ mode: Mode; pan: string }> = ({ mode, pan }) =>
  mode === "L" ? (
    <AbsoluteFill style={{ background: "#F3E4F7" }}>
      <Img src={staticFile("luana/bg.jpg")} style={{ position: "absolute", width: "100%", height: "100%", objectFit: "cover", transform: pan }} />
    </AbsoluteFill>
  ) : mode === "D" ? (
    <AbsoluteFill style={{ background: `radial-gradient(circle at 50% 45%, #3A1647 0%, ${NIGHT} 75%)` }} />
  ) : (
    <AbsoluteFill style={{ background: `radial-gradient(circle at 50% 40%, #A55DB4 0%, ${LIL} 55%, #7A3A8A 100%)` }} />
  );

// ───────── composição ─────────
export const VivatV4: React.FC = () => {
  const frame = useCurrentFrame();
  const t = frame / VV4_FPS - LEAD;

  // inundação de roxo escuro (sai do último passo da linha do tempo) e volta ao claro (sai do centro)
  // fundos em sequência: [quando começa, tipo, de onde sai o círculo]
  const BGS: [number, Mode, string][] = [
    [-99, "L", "50% 50%"],
    [S2 - 0.15, "D", "50% 64%"],
    [S3 - 0.15, "L", "50% 100%"],
    [S4 - 0.15, "P", "0% 45%"],
    [S5 - 0.15, "D", "20% 73%"],
    [S6 - 0.15, "L", "50% 22%"],
    [S7 - 0.2, "D", "50% 88%"],
    [S8 - 0.4, "L", "50% 40%"],
    [S9 - 0.15, "P", "50% 32%"],
  ];
  let j = 0;
  BGS.forEach(([a], i) => { if (t >= a) j = i; });
  const grow = io(t, BGS[j][0], BGS[j][0] + 0.7);
  const mode: Mode = grow > 0.5 || j === 0 ? BGS[j][1] : BGS[j - 1][1];
  const isDark = mode === "D";

  const bgZoom = 1.06 + 0.1 * lin(t, -LEAD, 45);
  // empurrão de câmera (sobe e volta em ~0,8 s) nas palavras-chave: ALERTA, CONFIRMOU, MENINGITE, RAPIDAMENTE, IMEDIATA, VACINAÇÃO EM DIA, logo
  const PUSH = [1.86, 5.08, 7.8, 25.12, 32.23, 38.01, 39.55];
  const push = PUSH.reduce((acc, p) => acc + (t > p && t < p + 0.8 ? Math.sin(((t - p) / 0.8) * Math.PI) * 0.035 : 0), 0);
  const bgPan = `translate(${(Math.sin(t * 0.21) * 18).toFixed(1)}px, ${(Math.cos(t * 0.17) * 22).toFixed(1)}px) scale(${bgZoom.toFixed(4)})`;

  // faixa do jornal no topo: S2 até o fim dos sintomas
  const barIn = k(t, S2 + 0.05, 0.6);
  const barOut = ein(t, S8 - 0.2, 0.35);

  return (
    <AbsoluteFill style={{ background: "#F3E4F7", overflow: "hidden" }}>
      {j > 0 && grow < 1 ? <Bg mode={BGS[j - 1][1]} pan={bgPan} /> : null}
      <AbsoluteFill style={{ clipPath: j > 0 && grow < 1 ? `circle(${(grow * 150).toFixed(2)}% at ${BGS[j][2]})` : undefined }}>
        <Bg mode={BGS[j][1]} pan={bgPan} />
      </AbsoluteFill>

      {/* ── faixa do jornal ── */}
      {t > S2 - 0.1 && t < S8 + 0.3 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: 170, display: "flex", justifyContent: "center", opacity: barIn * (1 - barOut), transform: `translateY(${((1 - barIn) * -30 + barOut * -30).toFixed(1)}px)` }}>
          <div style={{ display: "flex", alignItems: "center", borderRadius: 18, overflow: "hidden", boxShadow: "0 10px 30px rgba(43,16,53,0.18)" }}>
            <div style={{ background: isDark ? LIL : DEEP, color: WHITE, fontFamily: F, fontWeight: 700, fontSize: 34, letterSpacing: "0.08em", padding: "16px 24px 15px" }}>JORNAL VIVAT</div>
            <div style={{ background: isDark || mode === "P" ? WHITE : LIL, color: isDark || mode === "P" ? DEEP : WHITE, fontFamily: F, fontWeight: 500, fontSize: 34, letterSpacing: "0.06em", padding: "16px 26px 15px", display: "flex", alignItems: "center", gap: 12 }}>
              <span style={{ display: "inline-block", width: 14, height: 14, borderRadius: 7, background: isDark || mode === "P" ? LIL : WHITE, opacity: 0.55 + 0.45 * Math.abs(Math.sin(t * 2.4)) }} />
              ALERTA DE SAÚDE
            </div>
          </div>
        </div>
      ) : null}

      <AbsoluteFill style={{ transformOrigin: "50% 45%", transform: `scale(${(1 + push).toFixed(4)})` }}>
      {/* ── 1 · Notícia Vivat. Alerta de saúde! ── */}
      <Scene t={t} a={-LEAD} b={S2} enter="none" exit="zoom" drift={0.08} pan={[0, -30]}>
        <Col top={330}>
          <Mask t={t} at={-0.2}>
            <Img src={staticFile("luana/logo.png")} style={{ width: 420, display: "block" }} />
          </Mask>
        </Col>
        <Col top={720}>
          <div style={{ display: "flex", alignItems: "center", gap: 26 }}>
            <div style={{ width: 120, height: 4, background: LIL, borderRadius: 2, transformOrigin: "right", transform: `scaleX(${k(t, 0.1, 0.8)})` }} />
            <div style={{ display: "flex", gap: 18 }}>
              <Mask t={t} at={0.15}><Head size={58} color={LIL} ls="0.14em">NOTÍCIA</Head></Mask>
              <Mask t={t} at={0.98}><Head size={58} color={DEEP} ls="0.14em">VIVAT</Head></Mask>
            </div>
            <div style={{ width: 120, height: 4, background: LIL, borderRadius: 2, transformOrigin: "left", transform: `scaleX(${k(t, 0.1, 0.8)})` }} />
          </div>
        </Col>
        <Col top={860}>
          <div style={{ transform: `scale(${(0.85 + 0.15 * k(t, 1.7, 0.6)).toFixed(4)})`, opacity: k(t, 1.7, 0.3) }}>
            <IcoAlert s={170} c={DEEP} p={k(t, 1.7, 0.9)} w={1.6} />
          </div>
        </Col>
        <Col top={1080} gap={18}>
          <Mask t={t} at={1.86}><Head size={200} color={DEEP} ls="-0.035em">ALERTA</Head></Mask>
          <Pill t={t} at={2.36} size={112} bg={LIL}>DE SAÚDE</Pill>
        </Col>
      </Scene>

      {/* ── 2 · Secretaria da Saúde da Bahia confirmou ── */}
      <Scene t={t} a={S2} b={S3} enter="zoom" exit="up" drift={0.08} pan={[-30, 30]}>
        <Col top={640} gap={10}>
          <Mask t={t} at={3.38}><Head size={96} color={WHITE}>SECRETARIA</Head></Mask>
          <Mask t={t} at={3.9}><Head size={96} color={WHITE}>DA SAÚDE</Head></Mask>
          <Mask t={t} at={4.45}><Head size={96} color={LIL_L}>DA BAHIA</Head></Mask>
          <div style={{ height: 40 }} />
          <Pill t={t} at={5.08} size={104} bg={LIL}>CONFIRMOU</Pill>
        </Col>
      </Scene>

      {/* ── 3 · menina de 8 anos, meningite, Luís Eduardo Magalhães ── */}
      <Scene t={t} a={S3} b={S4} enter="up" exit="side" drift={0.05} pan={[0, 24]}>
        <Col top={300} gap={14}>
          <Mask t={t} at={6.4}><Head size={88} color={DEEP}>MENINA DE 8 ANOS</Head></Mask>
          <Pill t={t} at={7.8} size={84} bg={LIL}>MENINGITE</Pill>
        </Col>
        <Col top={575}>
          <div style={{ transform: `translateY(${((1 - k(t, S3 - 0.05, 1.0)) * 420).toFixed(1)}px) rotate(${((1 - k(t, S3 - 0.05, 1.1)) * -5).toFixed(2)}deg)`, opacity: k(t, S3 - 0.05, 0.4) }}>
            <DollCard t={t} w={760} h={930} p={lin(t, S3, S4)} />
          </div>
        </Col>
        <Col top={1570}>
          <div style={{ display: "flex", alignItems: "center", gap: 16, background: WHITE, borderRadius: 60, padding: "18px 34px 18px 26px", boxShadow: "0 14px 34px rgba(43,16,53,0.16)", opacity: k(t, 8.86, 0.35), transform: `translateY(${((1 - k(t, 8.86, 0.6)) * 40).toFixed(1)}px)` }}>
            <IcoPin s={50} c={LIL} p={k(t, 8.91, 0.8)} w={2.2} />
            <Mask t={t} at={8.96}><Head size={44} color={DEEP} weight={700}>Luís Eduardo Magalhães (BA)</Head></Mask>
          </div>
        </Col>
      </Scene>

      {/* ── 4 · segundo familiares: sintomas, atendimento, voltou para casa ── */}
      <Scene t={t} a={S4} b={S5} enter="side" exit="fade" drift={0.05} pan={[24, 30]}>
        <Col top={330}>
          <Mask t={t} at={10.71}><Head size={66} color={WHITE} ls="0.1em">SEGUNDO FAMILIARES</Head></Mask>
        </Col>
        <Steps t={t} />
      </Scene>

      {/* ── 5 · no dia seguinte, o quadro se agravou… não resistiu ── */}
      <Scene t={t} a={S5} b={S6} enter="none" exit="up" drift={0.1} pan={[0, 40]}>
        <Col top={780}>
          <Mask t={t} at={18.5} out={20.94}><Head size={60} color={LIL_L} ls="0.14em">NO DIA SEGUINTE</Head></Mask>
        </Col>
        <Col top={910} gap={8}>
          <Mask t={t} at={19.64} out={20.94}><Head size={128} color={WHITE}>O QUADRO</Head></Mask>
          <Mask t={t} at={20.14} out={20.94}><Head size={128} color={WHITE}>SE AGRAVOU</Head></Mask>
        </Col>
        {t > 20.94 ? (
          <>
            <Col top={780}>
              <Mask t={t} at={21.12}><Head size={60} color={LIL_L} ls="0.14em">INFELIZMENTE</Head></Mask>
            </Col>
            <Col top={910} gap={8}>
              <Mask t={t} at={22.14}><Head size={128} color={WHITE}>A MENINA</Head></Mask>
              <Mask t={t} at={22.59}><Head size={128} color={WHITE}>NÃO RESISTIU</Head></Mask>
            </Col>
            <Col top={1230}>
              <div style={{ width: 200, height: 4, borderRadius: 2, background: LIL, transform: `scaleX(${k(t, 22.94, 1.0)})` }} />
            </Col>
          </>
        ) : null}
      </Scene>

      {/* ── 6 · a meningite pode evoluir rapidamente ── */}
      <Scene t={t} a={S6} b={S7} enter="up" exit="none" drift={0.06} pan={[0, 24]}>
        <Col top={330} gap={12}>
          <Mask t={t} at={23.72} out={S7 - 0.1}><Head size={104} color={DEEP}>A MENINGITE</Head></Mask>
          <Mask t={t} at={24.42} out={S7 - 0.1}><Head size={74} color={LIL}>PODE EVOLUIR</Head></Mask>
          <Pill t={t} at={25.12} out={S7 - 0.1} size={88} bg={DEEP}>RAPIDAMENTE</Pill>
        </Col>
      </Scene>
      {/* o vírus sobe com a cena 6 e encolhe para baixo na troca para os sintomas */}
      {t > S6 - 0.1 && t < S7 + 0.6 ? (
        <Col top={790}>
          <div style={{ opacity: k(t, S6, 0.4) * (1 - ein(t, S7 - 0.05, 0.45)), transform: `translateY(${((1 - k(t, S6, 1.0)) * 420 + ein(t, S7 - 0.1, 0.5) * 420).toFixed(1)}px) scale(${(1 - 0.25 * ein(t, S7 - 0.1, 0.5)).toFixed(4)}) rotate(${((1 - k(t, S6, 1.1)) * 5).toFixed(2)}deg)` }}>
            <Photo src="luana/virus.jpg" w={760} h={700} zoom={1.05 + 0.2 * lin(t, S6, S7 + 0.5)} pos="45% 40%" />
          </div>
        </Col>
      ) : null}

      {/* ── 7 · sintomas e atenção médica imediata ── */}
      <Scene t={t} a={S7} b={S8 - 0.3} enter="none" exit="zoom" drift={0.06} pan={[-24, 30]}>
        <Col top={330}>
          <Mask t={t} at={26.25}><Head size={110} color={WHITE}>SINTOMAS</Head></Mask>
        </Col>
        <Col top={560} gap={34}>
          {([
            [27.1, "Febre", IcoThermo],
            [27.68, "Dor de cabeça intensa", IcoHead],
            [29.28, "Rigidez na nuca", IcoNeck],
          ] as [number, string, React.FC<IcoP>][]).map(([at, label, Ico], i) => (
            <div key={i} style={{ width: 840, height: 172, display: "flex", alignItems: "center", gap: 34, background: "rgba(255,255,255,0.07)", border: "2px solid rgba(217,184,226,0.22)", borderRadius: 34, padding: "0 36px", boxSizing: "border-box", opacity: k(t, at - 0.05, 0.35), transform: `translateX(${((1 - k(t, at - 0.05, 0.6)) * 80).toFixed(1)}px)` }}>
              <div style={{ width: 108, height: 108, borderRadius: 54, background: LIL, display: "flex", alignItems: "center", justifyContent: "center", flex: "none" }}>
                <Ico s={62} c={WHITE} p={k(t, at, 0.8)} w={2} />
              </div>
              <Mask t={t} at={at + 0.05}><Head size={56} color={WHITE} weight={700} ls="-0.01em">{label}</Head></Mask>
            </div>
          ))}
        </Col>
        <Col top={1250} gap={20}>
          <Mask t={t} at={30.63}><Head size={58} color={LIL_L} ls="0.1em">EXIGEM</Head></Mask>
          <Pill t={t} at={31.13} size={74} bg={WHITE} color={DEEP}>ATENÇÃO MÉDICA</Pill>
          <Pill t={t} at={32.23} size={74} bg={LIL}>IMEDIATA</Pill>
        </Col>
      </Scene>

      {/* ── 8 · vacinas protegem · mantenha a vacinação em dia ── */}
      <Scene t={t} a={S8} b={S9} enter="zoom" exit="none" drift={0.07} pan={[0, -40]}>
        <Col top={1120} gap={14}>
          <Mask t={t} at={33.24} out={37.38}><Head size={104} color={DEEP}>EXISTEM VACINAS</Head></Mask>
          <Mask t={t} at={34.39} out={37.38}><Head size={62} color={LIL} weight={500}>que protegem contra diferentes</Head></Mask>
          <Mask t={t} at={35.34} out={37.38}><Head size={62} color={LIL} weight={500}>causas da meningite</Head></Mask>
        </Col>
        {t > 37.38 ? (
          <Col top={1120} gap={14}>
            <Mask t={t} at={37.46}><Head size={92} color={LIL}>MANTENHA A</Head></Mask>
            <Pill t={t} at={38.01} size={80} bg={DEEP}>VACINAÇÃO EM DIA</Pill>
          </Col>
        ) : null}
      </Scene>
      {/* escudo: nasce na cena 8 e vira a Vivi no CTA */}
      {t > S8 - 0.1 && t < S9 + 0.6 ? (
        <Col top={500}>
          <div style={{ opacity: k(t, 33.19, 0.3) * (1 - ein(t, S9 - 0.05, 0.45)), transform: `perspective(1200px) rotateY(${((1 - k(t, 33.19, 1.2)) * -70).toFixed(2)}deg) scale(${(0.8 + 0.2 * k(t, 33.19, 0.8) + 0.05 * io(t, 33.5, S9) + ein(t, S9 - 0.05, 0.45) * 0.5).toFixed(4)})`, filter: `blur(${(ein(t, S9 - 0.05, 0.45) * 12).toFixed(1)}px)` }}>
            <Shield s={520} p={k(t, 33.24, 1.1)} chk={k(t, 38.86, 0.6)} />
          </div>
        </Col>
      ) : null}

      {/* ── 9 · CTA: Vivi + logo ── */}
      <Scene t={t} a={S9} b={99} enter="none" exit="none" drift={0.07} pan={[0, -40]}>
        <Col top={250}>
          <div style={{ opacity: k(t, S9 + 0.05, 0.35), transform: `translateY(${((1 - k(t, S9 + 0.05, 0.8)) * 120).toFixed(1)}px) scale(${(0.82 + 0.18 * k(t, S9 + 0.05, 0.8)).toFixed(4)})` }}>
            <Img src={staticFile("luana/vivi.png")} style={{ width: 640, display: "block" }} />
          </div>
        </Col>
        <Col top={1050}>
          <Mask t={t} at={39.55}>
            <Img src={staticFile("luana/logo-branco.png")} style={{ width: 560, display: "block" }} />
          </Mask>
        </Col>
        <Col top={1400} gap={6}>
          <Mask t={t} at={40.75}><Head size={66} color="#F3E4F7" weight={500}>está aqui para</Head></Mask>
          <Mask t={t} at={41.55}><Head size={80} color={WHITE}>orientar você.</Head></Mask>
        </Col>
      </Scene>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// linha do tempo da cena 4: quatro passos ligados por um fio que se desenha
const Steps: React.FC<{ t: number }> = ({ t }) => {
  const items: [number, string, React.FC<IcoP>][] = [
    [12.52, "Dor de cabeça", IcoHead],
    [14.24, "Dor no estômago", IcoStomach],
    [15.77, "Atendimento médico", IcoSteth],
    [17.15, "Voltou para casa", IcoHouse],
  ];
  const H = 210, G = 40, TOP = 540;
  const lineP = interpolate(t, [12.52, 12.92, 14.24, 14.62, 15.77, 16.17, 17.15, 17.57], [0, 0, 0.33, 0.33, 0.66, 0.66, 1, 1], cl);
  return (
    <>
      {/* fio */}
      <div style={{ position: "absolute", left: 120 + 36 + 62 - 2, top: TOP + H / 2, width: 4, height: (H + G) * 3, background: "rgba(255,255,255,0.3)", borderRadius: 2, opacity: k(t, 11.01, 0.5) }}>
        <div style={{ width: "100%", height: `${(lineP * 100).toFixed(2)}%`, background: WHITE, borderRadius: 2 }} />
      </div>
      {items.map(([at, label, Ico], i) => (
        <div key={i} style={{ position: "absolute", left: 120, top: TOP + i * (H + G), width: 840, height: H, display: "flex", alignItems: "center", gap: 36, padding: "0 36px", boxSizing: "border-box", background: WHITE, borderRadius: 40, boxShadow: "0 18px 44px rgba(43,16,53,0.22)", opacity: k(t, 11.01 + i * 0.14, 0.4) * (0.35 + 0.65 * k(t, at - 0.1, 0.35)), transform: `translateY(${((1 - k(t, 11.01 + i * 0.14, 0.7)) * 60).toFixed(1)}px)` }}>
          <div style={{ width: 124, height: 124, borderRadius: 62, background: i < 2 ? LIL : DEEP, display: "flex", alignItems: "center", justifyContent: "center", flex: "none", opacity: k(t, at - 0.1, 0.3), transform: `scale(${(0.6 + 0.4 * k(t, at - 0.1, 0.5)).toFixed(4)})` }}>
            <Ico s={66} c={WHITE} p={k(t, at, 0.8)} w={1.9} />
          </div>
          <Mask t={t} at={at + 0.05}><Head size={62} color={DEEP} ls="-0.02em">{label}</Head></Mask>
        </div>
      ))}
    </>
  );
};

